using System;using System.Text;using UnityEngine;using UnityEngine.InputSystem;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBeerPong {
public enum PongPhase{Countdown,Approach,Charging,Spring,Flight,Aftermath,Replay,TurnResult}
public sealed class PongMatch:SportsEventSession {
 public float AIPlannedCharge=>desiredCharge;public float AIPlannedYaw=>desiredYaw;public Vector3 CommandedLaunchVelocity{get;private set;}public PongAIPlayback aiPlayback;public SportsEventTruck truck;public PongShot shot;public PongCup[] cups;public Transform[] pads,coils;public Collider[] padContacts;public Collider table,floor;public SportsEventCamera cameraRig;public SportsMotionReplay replay;public ParticleSystem splash;public UnityEngine.UI.Image chargeFill;public GameObject practiceRetry;public TMPro.TMP_Text[] cupDiagrams;public PongRules rules=new PongRules();public int seed=7349;public PongPhase Phase{get;private set;}public float Clock{get;private set;}public float PhaseAge{get;private set;}public float FlightAge{get;private set;}public float Charge{get;private set;}public float AimYaw{get;private set;}public string Outcome{get;private set;}="";public readonly SportsLimitedAftertouch correction=new SportsLimitedAftertouch();public int TotalLaunches{get;private set;}public int Current=>rules.Shooter;public int Sign=>rules.ActiveTeam==0?1:-1;public bool Practice=>option==1;
 readonly StringBuilder text=new StringBuilder(700);Vector2 ai;float desiredCharge,desiredYaw,think;bool aiHold,chargeReleased=true,wasHeld,launchApplied;int aimCup,lastCupMask=-1;float launchPower;
 public override string Title=>"TRUCK BEER PONG";public override int MinimumPlayers=>Practice?1:2;public override int MaximumPlayers=>Practice?1:4;public override bool TeamSport=>!Practice;public override int OptionCount=>2;public override int WeatherCount=>1;public override bool ReplayControls=>Phase==PongPhase.Replay;public override string OptionLabel=>Practice?"SOLO PRACTICE":"1v1 / 2v2 HOUSE RULES";public override string SourcePolicy=>"Sequential shots. Teams have one or two players; teammates alternate.\nHot seat may reuse sources. Only the active shooter controls the truck.";
 public override void NormalizeSetup(){teamA=Mathf.Clamp(teamA,1,2);teamB=Mathf.Clamp(teamB,1,2);base.NormalizeSetup();setup.count=Practice?1:teamA+teamB;setup.mode=BowlingMode.HotSeat;setup.sharedHotSeat=true;}
 public override bool ValidateSources(out string reason){if(!setup.Validate(out reason))return false;for(int i=0;i<setup.count;i++){var p=setup.players[i];if(p.source==BowlingSource.Keyboard&&(actionKeys[i]==Key.None||actionKeys[i]==Key.Escape||actionKeys[i]==p.forward||actionKeys[i]==p.back||actionKeys[i]==p.left||actionKeys[i]==p.right)){reason="Assign a separate charge action for slot "+(i+1);return false;}}reason="";return true;}
 public override string Header=>Title+" · "+(Practice?"PRACTICE":rules.Overtime>0?"OVERTIME "+rules.Overtime:"TEN CUPS")+" · "+setup.players[Current].name+" · TEAM "+(rules.ActiveTeam==0?"BLUE":"ORANGE");
 public override string Status=>Phase==PongPhase.Countdown?"READY · "+Mathf.CeilToInt(2-PhaseAge):Phase==PongPhase.Approach?"DRIVE TO THE MARKED SPRING PAD · HOLD ACTION TO CHARGE":Phase==PongPhase.Charging?"HOLD ACTION · "+Mathf.RoundToInt(Charge*100)+"% · STEER TO AIM · RELEASE TO LAUNCH":Phase==PongPhase.Spring?"SPRING RELEASE":Phase==PongPhase.Flight?"LIMITED AFTERTOUCH · "+Mathf.RoundToInt(Mathf.Max(0,1-correction.Spent/1.6f)*100)+"%":Phase==PongPhase.Replay?"ACTUAL REPLAY · "+replay.Speed.ToString("0.##")+"× · CAMERA "+(replay.Angle+1):Outcome;
 public override string Standings{get{text.Clear().Append("BLUE ").Append(rules.remaining[0]).Append(" CUPS   |   ORANGE ").Append(rules.remaining[1]).Append(" CUPS\n").Append(rules.Period==PongPeriod.Rebuttal?"REBUTTAL · HIT TO CONTINUE\n":"ONE CUP MAX PER SHOT\n").Append("NEXT TEAMMATE · ").Append(setup.players[Practice?0:rules.NextTeammate].name);if(Practice)text.Append("\n").Append(rules.hits[0]).Append(" HITS / ").Append(rules.shots[0]).Append(" SHOTS · RACKS ").Append(rules.PracticeRacks);return text.ToString();}}
 public override string Results=>(rules.Winner==0?"BLUE":"ORANGE")+" WINS\n"+rules.hits[0]+" — "+rules.hits[1]+" CUPS · "+rules.Overtime+" OVERTIME PERIODS\n\n"+Standings;
 public override string Help=>"AI TURNS · Choose NORMAL, FAST-FORWARD or SIMULATE TO RESULT in setup or pause. Simulation uses the actual same fixed-step airborne physics and AI aftertouch, then shows the genuine cup result. Human turns are always normal.\n\nTHE TRUCK IS THE PROJECTILE\nDrive onto the outlined spring pad at your end. Hold your assigned ACTION to charge; steer left/right to aim. Release ACTION to commit the visible spring launch. Speed and aim come from your chosen power and direction, never automatic homing. After launch, small finite directional nudges share one correction budget. Release fore/aft once to arm range correction. First table/cup contact ends aftertouch; you cannot drive around the table.\n\nHOUSE RULES · 1v1 OR 2v2\nEach side starts with ten hollow red cups. Teams alternate one shot whether it hits or misses; teammates alternate their own team's shots. A legal shot enters an opposing live cup downward through the open top, then penetrates the interior. Rim-in and table-bounce shots each remove ONE cup. Rim brushes, exterior/side/bottom entry and flying over cups score nothing. Cup gaps remain; no swatting or drinking mechanics.\n\nREBUTTAL\nClearing the final cup gives the other side rebuttal. They keep shooting while hitting; their first miss loses. Clearing all remaining cups forces three-cup overtime. No counter-rebuttal. Overtime alternates the opening team and uses the same rebuttal rule; repeated overtime is allowed.\n\nSOLO PRACTICE has unlimited attempts and reracks only after clearing all ten. Sources may be shared between turns or assigned separately; inactive participants cannot interfere. Pause/reconnect preserves charge, flight and cups. Release then freshly hold after a modal confirmation; it cannot accidentally fire a charged shot. Recorded replay offers three angles, slow/fast, rewind and skip. Offline only.";
 protected override void BeginGame(){if(aiPlayback!=null)aiPlayback.ResetMatch();rules.Reset(teamA,teamB,Practice);TotalLaunches=0;Prepare();}
 void RestoreCups(){for(int i=0;i<cups.Length;i++)cups[i].gameObject.SetActive(rules.cups[cups[i].team,cups[i].index]);}
 void Prepare(){replay.End();RestoreCups();truck.slot=Current;truck.visuals.gameObject.SetActive(true);truck.Prepare(new Vector3(0,4.7f,-16*Sign),Quaternion.Euler(0,Sign==1?0:180,0));foreach(var c in padContacts)c.enabled=true;foreach(var p in pads){p.gameObject.SetActive(true);p.localScale=Vector3.one;}foreach(var c in coils)c.localScale=Vector3.one;shot.ResetShot();Clock=PhaseAge=FlightAge=Charge=AimYaw=0;Outcome="";Phase=PongPhase.Countdown;chargeReleased=true;wasHeld=launchApplied=false;correction.Reset(1.6f,Vector2.zero);splash.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);Plan();var colors=new Color[23];colors[0]=setup.players[Current].color;replay.Colorize(colors);replay.ResetRecord();cameraRig.rig.PreviousStateIsValid=false;Gate();Physics.SyncTransforms();}
 void Plan(){var rng=new System.Random(seed+rules.shots[0]*1297+rules.shots[1]*7919);int target=1-rules.ActiveTeam;aimCup=rng.Next(10);for(int i=0;i<10&&!rules.cups[target,aimCup];i++)aimCup=(aimCup+1)%10;var origin=new Vector3(0,5.15f,-10*Sign);var p=cups[target*10+aimCup].Center+Vector3.up*3.55f;float distance=Vector2.Distance(new Vector2(origin.x,origin.z),new Vector2(p.x,p.z));float low=0,high=1;for(int i=0;i<20;i++){float q=(low+high)*.5f,vy=10+6*q;float t=(vy+Mathf.Sqrt(vy*vy-2*9.81f*(p.y-origin.y)))/9.81f;if((14+16*q)*t<distance)low=q;else high=q;}float skill=(int)setup.players[Current].difficulty;desiredCharge=Mathf.Clamp01((low+high)*.5f+(float)(rng.NextDouble()*2-1)*Mathf.Lerp(.045f,.009f,skill*.5f));desiredYaw=Mathf.Atan2(p.x*Sign,(p.z-origin.z)*Sign)*Mathf.Rad2Deg+(float)(rng.NextDouble()*2-1)*Mathf.Lerp(3.5f,.45f,skill*.5f);think=0;ai=Vector2.zero;aiHold=false;}
 void Bot(float dt){think-=dt;if(think>0&&Phase!=PongPhase.Charging)return;think=.06f+(.1f-(int)setup.players[Current].difficulty*.04f);aiHold=false;var p=truck.body.position;if(Phase==PongPhase.Approach){var target=new Vector3(0,4.7f,-10*Sign);var d=target-p;float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(truck.body.rotation*Vector3.forward,Vector3.up),Vector3.ProjectOnPlane(d,Vector3.up),Vector3.up);float speed=Vector3.Dot(truck.body.linearVelocity,Vector3.forward*Sign);ai=new Vector2(Mathf.Clamp(angle/25,-1,1),d.z*Sign>1.6f?Mathf.Clamp((3-speed)*.8f,-1,1):0);aiHold=ReadyPad;}else if(Phase==PongPhase.Charging){ai=new Vector2(Mathf.Clamp((desiredYaw-AimYaw)*.15f,-1,1),0);aiHold=Charge<desiredCharge||Mathf.Abs(desiredYaw-AimYaw)>.25f;}else if(Phase==PongPhase.Flight&&!shot.Touched){var p2=truck.body.worldCenterOfMass;var v=truck.body.linearVelocity;var cup=cups[(1-rules.ActiveTeam)*10+aimCup];float discr=v.y*v.y+2*9.81f*(p2.y-cup.Top);float t=discr>0?(v.y+Mathf.Sqrt(discr))/9.81f:0;var predicted=p2+v*t;float error=(cup.Center.x-predicted.x)*Sign;ai=new Vector2(Mathf.Clamp(error*.12f,-.65f,.65f),FlightAge<.35f?0:Mathf.Clamp((cup.Center.z-predicted.z)*Sign*.07f,-.65f,.65f));}else ai=Vector2.zero;}
 public bool ReadyPad=>Mathf.Abs(truck.body.position.x)<2.1f&&Mathf.Abs(truck.body.position.z+10*Sign)<2.2f&&truck.Grounded&&Vector3.Dot(truck.body.rotation*Vector3.up,Vector3.up)>.65f;
 protected override void Simulate(float dt){Clock+=dt;PhaseAge+=dt;if(Phase==PongPhase.Flight)shot.Observe(dt);if(Phase==PongPhase.Replay){if(replay.Step(dt)||PhaseAge>18){replay.End();RestoreCups();truck.visuals.gameObject.SetActive(true);Phase=PongPhase.TurnResult;PhaseAge=0;}return;}if(Phase==PongPhase.TurnResult){if(PhaseAge>1){rules.Advance();if(rules.Complete)EndMatch();else Prepare();}return;}if(Phase==PongPhase.Countdown){Brake();if(PhaseAge>=2){Phase=PongPhase.Approach;PhaseAge=0;}return;}Vector2 drive=commands[Current];bool held=setup.players[Current].source==BowlingSource.AI?false:setup.players[Current].released&&ActionHeld(Current);if(setup.players[Current].source==BowlingSource.AI){Bot(dt);drive=ai;held=aiHold;}
  if(Phase==PongPhase.Approach){truck.TickDrive(drive);if(ReadyPad&&held&&chargeReleased){Phase=PongPhase.Charging;PhaseAge=0;Charge=0;AimYaw=Mathf.Clamp(Mathf.DeltaAngle(Sign==1?0:180,truck.body.rotation.eulerAngles.y),-26,26);truck.Power(false);truck.body.isKinematic=true;truck.body.position=new Vector3(0,5.15f,-10*Sign);truck.body.rotation=Quaternion.Euler(0,(Sign==1?0:180)+AimYaw,0);feedback.Play(0,0,true);}else if(PhaseAge>35||Mathf.Abs(truck.body.position.x)>18||truck.body.position.y<1||Mathf.Abs(truck.body.position.z)>45)Resolve(-1,"NO LAUNCH / OFF APPROACH");}
  else if(Phase==PongPhase.Charging){if(!chargeReleased){if(!held)chargeReleased=true;}else{if(held){Charge=Mathf.Min(1,Charge+dt*.32f);AimYaw=Mathf.Clamp(AimYaw+drive.x*dt*23,-26,26);truck.body.rotation=Quaternion.Euler(0,(Sign==1?0:180)+AimYaw,0);}if(wasHeld&&!held){launchPower=Charge;Phase=PongPhase.Spring;PhaseAge=0;launchApplied=false;feedback.Play(0,0,true);}}pads[rules.ActiveTeam].localScale=new Vector3(1,1-.35f*Charge,1);coils[rules.ActiveTeam].localScale=new Vector3(1,1-.6f*Charge,1);if(PhaseAge>35)Resolve(-1,"CHARGE TIMEOUT");}
  else if(Phase==PongPhase.Spring){float k=Mathf.Clamp01(PhaseAge/.25f);pads[rules.ActiveTeam].localScale=new Vector3(1,Mathf.Lerp(.65f,1.25f,Mathf.Sin(k*Mathf.PI)),1);coils[rules.ActiveTeam].localScale=new Vector3(1,Mathf.Lerp(.4f,1.4f,Mathf.Sin(k*Mathf.PI)),1);if(!launchApplied&&PhaseAge>=.12f){launchApplied=true;Launch(drive);}}
  else if(Phase==PongPhase.Flight){FlightAge+=dt;if(!shot.Touched)correction.Tick(truck.body,new Vector2(drive.x*Sign,drive.y*Sign),dt);if(FlightAge>16||truck.body.position.y<0||Mathf.Abs(truck.body.position.x)>40||Mathf.Abs(truck.body.position.z)>75)Resolve(-1,shot.Bounced?"BOUNCED OUT":"MISS");}
  else if(Phase==PongPhase.Aftermath){if(rules.LastHit){var cup=cups[(1-rules.ActiveTeam)*10+rules.LastCup];float t=Mathf.SmoothStep(0,1,Mathf.Clamp01(PhaseAge/.5f));truck.body.position=Vector3.Lerp(truck.body.position,cup.Center+Vector3.up*1.9f,t);truck.body.rotation=Quaternion.Slerp(truck.body.rotation,Quaternion.Euler(75,Sign==1?0:180,0),t);if(PhaseAge>.9f)cup.gameObject.SetActive(false);}if(PhaseAge>1.7f)BeginReplay();}
  wasHeld=held;replay.Record(Clock,VisibleMask());
 }
 public int SimulateAIFlight(int budget){
  if(!Live||setup.players[Current].source!=BowlingSource.AI||Phase!=PongPhase.Flight||Physics.simulationMode!=SimulationMode.FixedUpdate)return 0;
  var previousMode=Physics.simulationMode;int steps=0;
  try{Physics.simulationMode=SimulationMode.Script;while(steps<budget&&Live&&Phase==PongPhase.Flight&&!rules.ShotLocked){Simulate(Time.fixedDeltaTime);if(Phase==PongPhase.Flight)Physics.Simulate(Time.fixedDeltaTime);steps++;}}
  finally{Physics.simulationMode=previousMode;}
  if(rules.ShotLocked){replay.End();truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);RestoreCups();Phase=PongPhase.TurnResult;PhaseAge=0;Gate();}
  return steps;
 }
 public override void RefreshExtraUI(){foreach(var page in new[]{menus.pages[0],menus.pages[3]})foreach(var action in page.GetComponentsInChildren<SportsMenuAction>(true))if(action.action=="aipacing"){action.button.buttonText="AI TURNS: "+PongAIPlayback.Label;action.button.UpdateUI();}}
 void Brake(){truck.TickDrive(Vector2.zero);foreach(var w in truck.wheels){w.MotorTorque=0;w.BrakeTorque=truck.brakeTorque;}}
 void Launch(Vector2 drive){truck.body.isKinematic=false;truck.body.detectCollisions=true;padContacts[rules.ActiveTeam].enabled=false;var f=truck.body.rotation*Vector3.forward;var velocity=Vector3.ProjectOnPlane(f,Vector3.up).normalized*(14+16*launchPower)+Vector3.up*(10+6*launchPower);CommandedLaunchVelocity=velocity;truck.body.AddForce(velocity-truck.body.linearVelocity,ForceMode.VelocityChange);correction.Reset(1.6f,new Vector2(drive.x*Sign,drive.y*Sign));shot.Arm();TotalLaunches++;Phase=PongPhase.Flight;PhaseAge=FlightAge=0;feedback.Play(7,14,true);Pulse(Current,.35f,.16f);}
 public void Resolve(int cup,string reason){if(!Live||rules.ShotLocked)return;bool hit=cup>=0&&rules.TryHit(1-rules.ActiveTeam,cup);if(!hit&&!rules.Miss())return;Outcome=reason;Phase=PongPhase.Aftermath;PhaseAge=0;truck.Power(false);if(hit){truck.body.isKinematic=true;truck.body.detectCollisions=false;splash.transform.position=cups[(1-rules.ActiveTeam)*10+cup].Center+Vector3.up*2.5f;splash.Play();feedback.Play(4,0,true);feedback.Play(5,0,true);Pulse(Current,.6f,.22f);}else feedback.Play(3,0,true);Debug.Log("PONG_SHOT team="+rules.ActiveTeam+" shooter="+Current+" cup="+cup+" outcome="+reason+" contacts="+shot.Contacts+" bounced="+shot.Bounced);}
 int VisibleMask(){int mask=7;for(int i=0;i<cups.Length;i++)if(cups[i].gameObject.activeSelf)mask|=1<<(3+i);return mask;}
 void BeginReplay(){replay.Record(Clock+.051f,VisibleMask());truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);foreach(var cup in cups)cup.gameObject.SetActive(false);foreach(var p in pads)p.gameObject.SetActive(false);Phase=PongPhase.Replay;PhaseAge=0;replay.Begin(Mathf.Max(0,Clock-8));Gate();}
 public void CupImpact(float speed){feedback.Play(1,speed);Pulse(Current,.12f,.06f);}public void TableImpact(float speed){feedback.Play(2,speed);Pulse(Current,.18f,.08f);}
 public override void ExtraAction(string key){if(key=="aipacing"){aiPlayback.Cycle();return;}if(key=="ponga"&&!Running){teamA=teamA%2+1;Save();return;}if(key=="pongb"&&!Running){teamB=teamB%2+1;Save();return;}if(key=="retry"&&Practice&&Running&&!Paused){if(!rules.ShotLocked)rules.Miss();rules.Advance();Prepare();return;}if(Phase!=PongPhase.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")PhaseAge=19;ConsumeActions();}
 protected override void Present(float dt){if(aiPlayback!=null)aiPlayback.Tick();if(truck==null||cameraRig==null)return;bool recorded=Phase==PongPhase.Replay;var focus=recorded?replay.Position(0):truck.body.worldCenterOfMass;if(!recorded&&(Phase==PongPhase.Approach||Phase==PongPhase.Countdown||Phase==PongPhase.Charging))focus+=Vector3.forward*Sign*10;var offset=recorded?(replay.Angle==0?new Vector3(10,6,-12*Sign):replay.Angle==1?new Vector3(-12,6,9*Sign):new Vector3(0,24,-3*Sign)):Phase==PongPhase.Flight?new Vector3(0,5,-11*Sign):new Vector3(0,5,-12*Sign);cameraRig.Pose(focus,offset,64);if(practiceRetry!=null&&practiceRetry.activeSelf!=Practice)practiceRetry.SetActive(Practice);if(chargeFill!=null){chargeFill.fillAmount=Charge;chargeFill.rectTransform.localScale=new Vector3(Charge,1,1);}int mask=0;for(int i=0;i<20;i++)if(rules.cups[i/10,i%10])mask|=1<<i;if(cupDiagrams!=null&&mask!=lastCupMask){lastCupMask=mask;for(int team=0;team<2;team++){text.Clear();for(int row=0,start=0;row<4;row++){text.Append(' ',(3-row)*2);for(int col=0;col<=row;col++)text.Append(rules.cups[team,start+col]?"● ":"· ");text.Append('\n');start+=row+1;}cupDiagrams[team].text=text.ToString();}}}
 protected override void SetPaused(bool paused){if(paused){if(aiPlayback!=null)aiPlayback.Release();chargeReleased=false;wasHeld=false;}}
 protected override void StopSounds(){if(truck!=null)truck.StopSound();}protected override void StopGame(){if(aiPlayback!=null)aiPlayback.Release();if(replay!=null)replay.End();foreach(var p in pads)if(p!=null)p.gameObject.SetActive(true);if(truck!=null){truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;}}
}
}
